body.fast-hands-club .level-main{
  grid-template-columns:minmax(0,1fr);
  grid-template-areas:"header" "nav" "scene" "scores" "feedback" "control";
  grid-template-rows:44px 44px minmax(var(--club-stage-min),1fr) var(--club-hud) var(--club-feedback) auto;
  gap:var(--club-gap);
}
body.fast-hands-club .level-header{grid-area:header;display:flex;align-items:center;gap:8px;height:44px;min-width:0}
