body.fast-hands-club .level-hud{grid-area:scores;display:grid;grid-template-columns:1fr 1.65fr 1fr;height:var(--club-hud);min-height:0;padding:3px 0;align-self:stretch}
body.fast-hands-club .level-hud span{font-size:10px;line-height:13px}
