body.fast-hands-club .round-feedback{grid-area:feedback;display:grid;grid-template-rows:24px 19px 23px;row-gap:3px;align-content:center;align-self:stretch;height:var(--club-feedback);min-height:var(--club-feedback);max-height:var(--club-feedback)}
body.fast-hands-club .round-feedback>.eyebrow{display:none}
body.fast-hands-club .round-feedback h2{height:24px;min-height:24px;font-size:20px;line-height:24px;margin:0;letter-spacing:-.4px;align-items:center}
