body.fast-hands-club .level-controls{grid-area:control;display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:var(--club-primary) 15px 44px;gap:3px;align-self:stretch;width:100%;justify-self:stretch;position:static;padding:0;margin:0;background:none}
