body.fast-hands-club .level-help-content{position:absolute;z-index:12;right:0;left:0;bottom:48px;width:100%;max-height:min(390px,65dvh);overflow:auto;overscroll-behavior:contain;padding:12px 15px;background:#fffaf4;border:1px solid var(--line);border-radius:14px;box-shadow:0 8px 24px #18342833}
