body.fast-hands-club dialog{box-sizing:border-box;border:1.5px solid #b9c9ae;border-radius:22px;width:calc(100% - 24px);max-width:460px;max-height:calc(100dvh - 24px - env(safe-area-inset-top) - env(safe-area-inset-bottom));padding:0;background:var(--cream);color:var(--green);box-shadow:0 18px 80px #173f3940;overscroll-behavior:contain}
