body.fast-hands-club .result-dialog[open]{display:flex;flex-direction:column;grid-template-columns:none;gap:0;padding:0;text-align:center;overflow:hidden}
body.fast-hands-club .result-top,
body.fast-hands-club .summary-overview{position:relative;display:block;flex-shrink:0;flex-grow:0;padding:18px 22px 14px;margin:0;background:var(--gold);border-bottom:1px dashed #c0ad7d;border-right:0;text-align:center}
body.fast-hands-club .result-top>.ticket-kicker,
