body.fast-hands-club .result-top h2,
body.fast-hands-club .summary-overview h2{font-size:23px;line-height:1.3;margin:10px 25px 4px;letter-spacing:0}
body.fast-hands-club .result-summary{display:flex;flex-direction:row;justify-content:center;align-items:center;gap:12px;margin:8px 0 4px}
