body.fast-hands-club .result-dialog .ticket-body{display:flex;flex-direction:column;flex:1;min-height:0;overflow-x:visible;overflow-y:auto;padding:12px 18px 16px;overscroll-behavior:contain;scroll-padding-top:116px}
body.fast-hands-club .result-buttons{order:-1;position:sticky;top:-12px;z-index:3;flex-shrink:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;background:var(--cream);padding:12px 0 10px;margin-top:-12px}
