body.fast-hands-club .result-dialog .ticket-body>.level-switch{margin:12px 0 0;padding:0;border:0;flex-shrink:0}
body.fast-hands-club .result-dialog .ticket-note{font-size:10px;margin-top:10px;flex-shrink:0}
