body.fast-hands-club .close-button{position:absolute;top:8px;right:8px;width:44px;height:44px;min-height:44px;min-width:44px;padding:0;border:1px solid #17494115;border-radius:50%;background:#fff9e97a;color:var(--green);font-size:27px;line-height:1;font-weight:500;cursor:pointer}
