import {handlePlayCounts} from '../play-counts/index.mjs';
import {LeaderboardRepository} from './repository.mjs';
import {NOTE_FLOOR_MS} from '../../public/games/fast-hands/challenge.mjs';
export const BOARDS=Object.freeze({
 'long-jump':Object.freeze({rules:'journey-km-v1',unit:'km',status:'valid',direction:'desc',max:Number.MAX_VALUE}),
 hurdles:Object.freeze({rules:'110m-8h-v1',unit:'s',status:'done',direction:'asc',max:180}),
 'high-jump':Object.freeze({rules:'cleared-height-v1',unit:'m',status:'cleared',direction:'desc',max:Number.MAX_VALUE}),
 'pole-vault':Object.freeze({rules:'highest-feet-v1',unit:'m',status:'done',direction:'desc',max:Number.MAX_VALUE}),
 'shot-put':Object.freeze({rules:'relay-distance-v1',unit:'m',status:'valid',direction:'desc',max:Number.MAX_VALUE}),
 discus:Object.freeze({rules:'wind-ufo-distance-v1',unit:'m',status:'valid',direction:'desc',max:Number.MAX_VALUE}),
 'reaction-rod':Object.freeze({rules:'catch-rating-v1',unit:'catches',status:'done',direction:'desc',max:10,secondary:true}),
 'beer-slide':Object.freeze({rules:'accuracy-retention-v1',unit:'points',status:'valid',direction:'desc',max:10}),
 'tower-climb':Object.freeze({rules:'indoor-10floors-v1',unit:'s',status:'summit',direction:'asc',max:60})
});
// Fast Hands rules isolate the two input modes without changing the nine legacy boards.
export const FAST_HANDS_BOARDS=Object.freeze({
 mouse:Object.freeze({rules:'shuttle-v3-mouse',unit:'ms',status:'success',direction:'asc',max:NOTE_FLOOR_MS,exclusiveMax:true}),
 touch:Object.freeze({rules:'shuttle-v3-touch',unit:'ms',status:'success',direction:'asc',max:NOTE_FLOOR_MS,exclusiveMax:true})
});
export const LEVEL_BOARDS=Object.freeze({
 'fast-hands-catch':Object.freeze({rules:'cleared-levels-v1',unit:'levels',status:'done',direction:'desc',max:Number.MAX_SAFE_INTEGER,integer:true}),
 'fast-hands-duel':Object.freeze({rules:'ten-round-wins-v1',unit:'wins',status:'done',direction:'desc',max:10,integer:true})
});
const isLevel=game=>typeof game==='string'&&Object.hasOwn(LEVEL_BOARDS,game);
const isFast=game=>game==='fast-hands'||isLevel(game);
function resolveBoard(game,rules){
 if(isLevel(game))return LEVEL_BOARDS[game];
 if(game==='fast-hands')return Object.values(FAST_HANDS_BOARDS).find(board=>board.rules===rules)??null;
 return typeof game==='string'&&Object.hasOwn(BOARDS,game)?BOARDS[game]:null;
}
const fields=['game','rules','unit','status','score','nickname','deviceId','submissionId'];
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
export function validateSubmission(value){
 if(!value||Array.isArray(value)||typeof value!=='object'||(Object.keys(value).length!==fields.length&&Object.keys(value).length!==fields.length+1)||fields.some(k=>!Object.hasOwn(value,k))||Object.keys(value).some(k=>!fields.includes(k)&&k!=='secondaryScore'))throw Error('invalid_fields');
 if(isFast(value.game)&&Object.keys(value).length!==fields.length)throw Error('invalid_fields');
 const b=resolveBoard(value.game,value.rules);if(!b||value.rules!==b.rules||value.unit!==b.unit||value.status!==b.status)throw Error('invalid_board');
 if(typeof value.score!=='number'||!Number.isFinite(value.score)||value.score<=0||value.score>b.max||(b.integer&&!Number.isSafeInteger(value.score))||(b.exclusiveMax&&value.score===b.max))throw Error('invalid_score');
 if(b.secondary){if(!Number.isInteger(value.score)||typeof value.secondaryScore!=='number'||!Number.isFinite(value.secondaryScore)||value.secondaryScore<0||value.secondaryScore>10)throw Error('invalid_secondary');}
 else if(Object.hasOwn(value,'secondaryScore')&&value.secondaryScore!==0)throw Error('invalid_secondary');
 if(typeof value.nickname!=='string'||value.nickname!==value.nickname.trim()||[...value.nickname].length<1||[...value.nickname].length>20||new TextEncoder().encode(value.nickname).length>80||/[<>\p{Cc}\p{Cf}]/u.test(value.nickname))throw Error('invalid_nickname');
 if(typeof value.deviceId!=='string'||typeof value.submissionId!=='string'||!uuid.test(value.deviceId)||!uuid.test(value.submissionId))throw Error('invalid_id');
 return Object.fromEntries([...fields,...(b.secondary?['secondaryScore']:[])].map(k=>[k,k==='deviceId'||k==='submissionId'?value[k].toLowerCase():value[k]]));
}
function parseSubmission(text){
 const value=JSON.parse(text);
 if(isFast(value?.game)){
  // JSON.parse alone silently keeps the last duplicate key. Scan complete string tokens
  // so escaped property names are compared correctly and quoted nickname text is ignored.
  const keys=new Set();
  for(const token of text.matchAll(/"(?:[^"\\]|\\.)*"/g)){
   if(!text.slice(token.index+token[0].length).trimStart().startsWith(':'))continue;
   const key=JSON.parse(token[0]);if(keys.has(key))throw Error('invalid_fields');keys.add(key);
  }
 }
 return validateSubmission(value);
}
const json=(body,status=200,extra={})=>new Response(JSON.stringify(body),{status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff',...extra}});
export async function handleRequest(request,env,now=Date.now()){
 const url=new URL(request.url);
 if(url.pathname.startsWith('/api/play-counts'))return handlePlayCounts(request,env,now);
 if(!url.pathname.startsWith('/api/leaderboard'))return env.ASSETS?.fetch(request)??new Response('Not found',{status:404});
 if(env.LEADERBOARD_ENABLED!=='true'||!['qa','production'].includes(env.LEADERBOARD_SCOPE)||!env.DB||env.LEADERBOARD_ORIGIN!==url.origin)return json({error:'unavailable'},503);
 const repo=new LeaderboardRepository(env.DB,env.LEADERBOARD_SCOPE);
 try{
  if(request.method==='GET'&&url.pathname==='/api/leaderboard'){
   const game=url.searchParams.get('game'),fast=game==='fast-hands',mode=url.searchParams.get('mode');
   const board=fast?(Object.hasOwn(FAST_HANDS_BOARDS,mode)?FAST_HANDS_BOARDS[mode]:null):resolveBoard(game);
   const invalidQuery=fast
    ?url.searchParams.getAll('game').length!==1||url.searchParams.getAll('mode').length!==1||[...url.searchParams.keys()].some(k=>k!=='game'&&k!=='mode')
    :(isLevel(game)&&url.searchParams.getAll('game').length!==1)||[...url.searchParams.keys()].some(k=>k!=='game');
   if(!board||invalidQuery)return json({error:'invalid_board'},400);
   if(isFast(game)&&env.LEADERBOARD_SCOPE!=='qa')return json({error:'unavailable'},503);
   const device=request.headers.get('X-Leaderboard-Device');if(device!==null&&!uuid.test(device))return json({error:'invalid_id'},400);
   return json({game,rules:board.rules,unit:board.unit,...await repo.board(game,board,device?.toLowerCase())},200,{'Cache-Control':device?'private, no-store':'public, max-age=30','Vary':'X-Leaderboard-Device'});
  }
  if(request.method!=='POST'||url.pathname!=='/api/leaderboard/submissions')return json({error:'method_not_allowed'},405);
  if(request.headers.get('Origin')!==env.LEADERBOARD_ORIGIN)return json({error:'origin'},403);
  if(!/^application\/json(?:;|$)/i.test(request.headers.get('Content-Type')||''))return json({error:'content_type'},415);
  if(Number(request.headers.get('Content-Length'))>2048)return json({error:'too_large'},413);
  const reader=request.body?.getReader();if(!reader)return json({error:'invalid_body'},400);
  let total=0,chunks=[];while(true){const {done,value}=await reader.read();if(done)break;total+=value.byteLength;if(total>2048){await reader.cancel();return json({error:'too_large'},413);}chunks.push(value);}
  const bytes=new Uint8Array(total);let off=0;for(const c of chunks){bytes.set(c,off);off+=c.length;}
  let data;try{data=parseSubmission(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}catch{return json({error:'invalid_submission'},400);}
  if(isFast(data.game)){
   if(url.search)return json({error:'invalid_submission'},400);
   if(env.LEADERBOARD_SCOPE!=='qa')return json({error:'unavailable'},503);
  }
  const result=await repo.submit(data,resolveBoard(data.game,data.rules),now);
  return json(result,result.error==='conflict'?409:result.error==='limited'?429:200,result.error==='limited'?{'Retry-After':'60'}:{});
 }catch{return json({error:'temporarily_unavailable'},503);}
}
export default {fetch(request,env){return handleRequest(request,env);}};

const digest=async text=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))].map(x=>x.toString(16).padStart(2,'0')).join('');
export class LeaderboardRepository {
 constructor(db,scope){this.db=db;this.scope=scope;}
 ordering(b){return `score ${b.direction==='asc'?'ASC':'DESC'}${b.secondary?',secondary_score DESC':''},device ASC`;}
 better(b,left,right){const op=b.direction==='asc'?'<':'>';return b.secondary?`(${left}.score,${left}.secondary_score)>(${right}.score,${right}.secondary_score)`:`${left}.score ${op} ${right}.score`;}
 async top(game,b){return (await this.board(game,b)).entries.map(({nickname,score,...rest})=>({nickname,score,...(b.secondary?{secondaryScore:rest.secondaryScore}:{})}));}
 ownQuery(game,b,device){
  const better=this.better(b,'other','me'),reverse=b.direction==='asc'?'DESC':'ASC';
  const from=`FROM leaderboard_best other WHERE other.scope=me.scope AND other.game=me.game AND other.rules=me.rules AND ${better}`;
  const order=`ORDER BY other.score ${reverse}${b.secondary?',other.secondary_score ASC':''} LIMIT 1`;
  return this.db.prepare(`SELECT me.nickname,me.score,me.secondary_score,
   (SELECT count(*)+1 ${from}) AS rank,
   (SELECT other.score ${from} ${order}) AS previous,
   (SELECT other.secondary_score ${from} ${order}) AS previous_secondary
   FROM leaderboard_best me WHERE me.scope=? AND me.game=? AND me.rules=? AND me.device=?`).bind(this.scope,game,b.rules,device||'');
 }
 ownRow(row,b){if(!row)return null;const secondaryGap=b.secondary&&row.previous===row.score;return {nickname:row.nickname,score:row.score,rank:Number(row.rank),gap:row.previous===null?null:Math.abs(secondaryGap?row.previous_secondary-row.secondary_score:row.previous-row.score),...(b.secondary?{secondaryScore:row.secondary_score,gapMetric:row.previous===null?null:secondaryGap?'rating':'catches'}:{})};}
 async own(game,b,deviceId){return deviceId?this.ownRow(await this.ownQuery(game,b,await digest(this.scope+':'+deviceId)).first(),b):null;}
 async board(game,b,deviceId=null){
  const device=deviceId?await digest(this.scope+':'+deviceId):null;
  const result=await this.db.batch([
   this.db.prepare(`SELECT nickname,score,secondary_score,device FROM leaderboard_best WHERE scope=? AND game=? AND rules=? ORDER BY ${this.ordering(b)} LIMIT 20`).bind(this.scope,game,b.rules),this.ownQuery(game,b,device)]);
  let rank=0,prior=null,secondary=null;const entries=result[0].results.map((row,i)=>{if(row.score!==prior||(b.secondary&&row.secondary_score!==secondary))rank=i+1;prior=row.score;secondary=row.secondary_score;return {nickname:row.nickname,score:row.score,rank,isMe:device!==null&&row.device===device,...(b.secondary?{secondaryScore:row.secondary_score}:{})};});
  return {entries,own:this.ownRow(result[1].results[0],b)};
 }
 async submit(data,b,now){
  const device=await digest(this.scope+':'+data.deviceId),payload=await digest(JSON.stringify(data)),day=Math.floor(now/86400000);
  const p=(sql,...args)=>this.db.prepare(sql).bind(...args);
  const existing=await p('SELECT payload FROM leaderboard_submissions WHERE scope=? AND id=?',this.scope,data.submissionId).first();
  if(existing)return existing.payload===payload?{accepted:true,duplicate:true,bestUpdated:false,own:await this.own(data.game,b,data.deviceId)}:{error:'conflict'};
  const rows=await this.db.batch([
   p('SELECT payload FROM leaderboard_submissions WHERE scope=? AND id=?',this.scope,data.submissionId),
   p('SELECT score,secondary_score FROM leaderboard_best WHERE scope=? AND game=? AND rules=? AND device=?',this.scope,data.game,data.rules,device),
   p('DELETE FROM leaderboard_submissions WHERE rowid IN (SELECT rowid FROM leaderboard_submissions WHERE scope=? AND created_at<? LIMIT 100)',this.scope,now-7*86400000),
   p(`INSERT OR IGNORE INTO leaderboard_submissions(scope,id,payload,device,game,rules,nickname,score,created_at,day,secondary_score)
    SELECT ?,?,?,?,?,?,?,?,?,?,? WHERE
    NOT EXISTS(SELECT 1 FROM leaderboard_submissions WHERE scope=? AND device=? AND created_at>?)
    AND (SELECT count(*) FROM leaderboard_submissions WHERE scope=? AND day=?)<1000
    AND (EXISTS(SELECT 1 FROM leaderboard_best WHERE scope=? AND game=? AND rules=? AND device=?) OR (SELECT count(*) FROM leaderboard_best WHERE scope=?)<10000)`,this.scope,data.submissionId,payload,device,data.game,data.rules,data.nickname,data.score,now,day,data.secondaryScore??0,this.scope,device,now-60000,this.scope,day,this.scope,data.game,data.rules,device,this.scope),
   p(`INSERT INTO leaderboard_best(scope,game,rules,device,nickname,score,updated_at,secondary_score)
     SELECT scope,game,rules,device,nickname,score,created_at,secondary_score FROM leaderboard_submissions WHERE scope=? AND id=? AND payload=?
     ON CONFLICT(scope,game,rules,device) DO UPDATE SET nickname=excluded.nickname,score=excluded.score,updated_at=excluded.updated_at,secondary_score=excluded.secondary_score
     WHERE ${this.better(b,'excluded','leaderboard_best')}`,this.scope,data.submissionId,payload),
   p('SELECT score,secondary_score FROM leaderboard_best WHERE scope=? AND game=? AND rules=? AND device=?',this.scope,data.game,data.rules,device),
   p('SELECT payload FROM leaderboard_submissions WHERE scope=? AND id=?',this.scope,data.submissionId)
  ]);
  const accepted=rows.at(-1).results?.[0];if(!accepted)return {error:'limited'};if(accepted.payload!==payload)return {error:'conflict'};
  const duplicate=Boolean(rows[0].results?.length),before=rows[1].results?.[0],after=rows.at(-2).results?.[0];
  return {accepted:true,duplicate,bestUpdated:!duplicate&&after!==undefined&&(before===undefined||after.score!==before.score||after.secondary_score!==before.secondary_score),own:await this.own(data.game,b,data.deviceId)};
 }
}
